class Solution:
    def countSubarrays(self, nums, k):
        ans = 0
        cur = []
        for x in nums:
            nxt = [[x, 1]]
            for v, c in cur:
                w = v & x
                if nxt[-1][0] == w:
                    nxt[-1][1] += c
                else:
                    nxt.append([w, c])
            cur = nxt
            for v, c in cur:
                if v == k:
                    ans += c
        return ans

