class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long ans = 0;
        vector<pair<int,long long>> cur;
        for (int x : nums) {
            vector<pair<int,long long>> nxt{{x, 1}};
            for (auto& [v, c] : cur) {
                int w = v & x;
                if (nxt.back().first == w) nxt.back().second += c;
                else nxt.push_back({w, c});
            }
            cur = move(nxt);
            for (auto& [v, c] : cur)
                if (v == k) ans += c;
        }
        return ans;
    }
};

