class Solution {
    public long countSubarrays(int[] nums, int k) {
        long ans = 0;
        List<long[]> cur = new ArrayList<>();
        for (int x : nums) {
            List<long[]> nxt = new ArrayList<>();
            nxt.add(new long[]{x, 1});
            for (long[] p : cur) {
                int w = (int)p[0] & x;
                if (!nxt.isEmpty() && (int)nxt.get(nxt.size()-1)[0] == w)
                    nxt.get(nxt.size()-1)[1] += p[1];
                else nxt.add(new long[]{w, p[1]});
            }
            cur = nxt;
            for (long[] p : cur) if ((int)p[0] == k) ans += p[1];
        }
        return ans;
    }
}

