class Solution {
public:
    vector<vector<int>> sp;
    int qry(int l, int r) {
        int j = __lg(r - l + 1);
        return sp[j][l] & sp[j][r - (1 << j) + 1];
    }
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        sp.assign(__lg(n) + 1, {});
        sp[0] = nums;
        for (int j = 1; (1 << j) <= n; j++) {
            sp[j].resize(n - (1 << j) + 1);
            for (int i = 0; i + (1 << j) <= n; i++)
                sp[j][i] = sp[j-1][i] & sp[j-1][i + (1 << (j-1))];
        }
        long long ans = 0;
        for (int r = 0; r < n; r++) {
            int l = r;
            while (l >= 0) {
                int v = qry(l, r);
                int lo = 0, hi = l;
                while (lo < hi) {
                    int mid = (lo + hi) / 2;
                    if (qry(mid, r) == v) hi = mid; else lo = mid + 1;
                }
                if (v == k) ans += l - lo + 1;
                l = lo - 1;
            }
        }
        return ans;
    }
};

