var countSubarrays = function(nums, k) {
    const n = nums.length;
    const sp = [nums.slice()];
    for (let j = 1; (1 << j) <= n; j++) {
        const prev = sp[j-1], len = n - (1 << j) + 1, row = [];
        for (let i = 0; i < len; i++) row.push(prev[i] & prev[i + (1 << (j-1))]);
        sp.push(row);
    }
    const qry = (l, r) => {
        let j = 0; while ((2 << j) <= r - l + 1) j++;
        return sp[j][l] & sp[j][r - (1 << j) + 1];
    };
    let ans = 0;
    for (let r = 0; r < n; r++) {
        let l = r;
        while (l >= 0) {
            const v = qry(l, r);
            let lo = 0, hi = l;
            while (lo < hi) {
                const mid = (lo + hi) >> 1;
                if (qry(mid, r) === v) hi = mid; else lo = mid + 1;
            }
            if (v === k) ans += l - lo + 1;
            l = lo - 1;
        }
    }
    return ans;
};
